 toggle.addEventListener('click',()=>{if(active)setSidebar(sidebar.hidden);});$('#file-sidebar-close').addEventListener('click',()=>setSidebar(false));$('#file-drawer-shade').addEventListener('click',()=>setSidebar(false));$('#file-location-form').addEventListener('submit',e=>{e.preventDefault();const value=pathInput.value.trim();if(value.startsWith('/'))load(value,{navigate:true});else treeNote('请输入以 / 开头的完整路径',true);});
 $('#file-root').addEventListener('click',()=>load('/',{navigate:true}));$('#file-home').addEventListener('click',()=>load('/',{navigate:true,action:'home'}));$('#file-up').addEventListener('click',()=>load(root.split('/').slice(0,-1).join('/')||'/',{navigate:true}));$('#file-refresh').addEventListener('click',()=>{cache.clear();expanded.clear();load(root,{navigate:true});});
 $('#terminal-tab').addEventListener('click',()=>view('terminal'));$('#file-tab').addEventListener('click',()=>view('file'));$('#file-close').addEventListener('click',async()=>{if(!await confirmDiscard())return;current=null;input.value='';baseline='';$('#file-tab').hidden=true;$('#file-close').hidden=true;view('terminal');});
 const separator=$('#file-resizer');let resizing=false;const width=value=>{const n=Math.max(200,Math.min(420,dialog.clientWidth*.48,value));dialog.style.setProperty('--file-width',n+'px');separator.setAttribute('aria-valuenow',String(Math.round(n)));onResize();};separator.addEventListener('pointerdown',e=>{if(!active)return;resizing=true;separator.setPointerCapture(e.pointerId);e.preventDefault();});separator.addEventListener('pointermove',e=>{if(resizing)width(e.clientX-dialog.getBoundingClientRect().left);});separator.addEventListener('pointerup',()=>{resizing=false;});separator.addEventListener('lostpointercapture',()=>{resizing=false;});separator.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();width(sidebar.clientWidth+(e.key==='ArrowLeft'?-20:20));}});
 const beforeUnload=e=>{if(dirty()||transfer){e.preventDefault();e.returnValue='';}};window.addEventListener('beforeunload',beforeUnload);
 function clear(){if(transfer)transfer.cancel=true;transfer=null;progress.hidden=true;uploadButton.disabled=true;mkdirButton.disabled=true;newFileButton.disabled=true;finishName(null);generation++;active=false;saving=false;opening=false;current=null;baseline='';input.value='';input.disabled=false;input.readOnly=false;cache.clear();expanded.clear();tree.replaceChildren();root='/';pathInput.value='/';for(const p of pending.values()){clearTimeout(p.timer);p.reject(Error('SSH 连接已结束'));}pending.clear();toggle.disabled=true;setSidebar(false);$('#file-tab').hidden=true;$('#file-close').hidden=true;$('#file-name').textContent='';$('#file-meta').textContent='';note('');treeNote('连接 SSH 后浏览文件');resolveDiscard(false);view('terminal');}
